const input = $input.first().json;
const headers = input.headers ?? {};
const received = Object.entries(headers).find(([name]) => name.toLowerCase() === 'x-ecoscan-secret')?.[1];
const expected = $env.N8N_SHARED_SECRET;
if (!expected || expected.startsWith('replace-with-') || !received || received !== expected) throw new Error('Unauthorized billing reminder webhook request');
const payload = input.body ?? input;
const id = String(payload.relance_id ?? '');
if (!/^[0-9a-f-]{36}$/i.test(id)) throw new Error('Invalid reminder identifier');
const backend = String($env.BACKEND_BASE_URL ?? '').replace(/\/$/, '');
if (!/^https?:\/\//i.test(backend)) throw new Error('BACKEND_BASE_URL must be configured');
const callback_url = `${backend}/api/paiements/relances/${id}/callback/`;
const recipients = payload.organisation?.emails_admin;
const canalEmail = String(payload.canal ?? '').toUpperCase() === 'EMAIL';
const validRecipients = Array.isArray(recipients) && recipients.length > 0 && recipients.every((email) => typeof email === 'string' && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email));
const facture = payload.facture ?? {};
const should_send = canalEmail && validRecipients && Boolean(payload.organisation?.nom && facture.numero && facture.montant_total && facture.date_echeance);
const detail = !canalEmail ? `Canal ${payload.canal ?? 'inconnu'} non pris en charge par ce workflow (e-mail uniquement).` : !validRecipients ? 'Aucune adresse e-mail administrateur valide.' : !should_send ? 'Données de facturation incomplètes.' : '';
const text = [
  `Bonjour,`,
  '',
  `Une facture EcoScan ${facture.numero ?? ''} de ${facture.montant_total ?? ''} ${facture.devise ?? ''} pour ${payload.organisation?.nom ?? ''} nécessite votre attention.`,
  `Échéance : ${facture.date_echeance ?? ''}`,
  `Niveau de relance : ${payload.niveau ?? ''}`,
  '',
  'Connectez-vous à EcoScan pour consulter la facture et régulariser votre abonnement.',
  '',
  'L’équipe EcoScan'
].join('\n');
return [{ json: { relance_id: id, callback_url, recipients: validRecipients ? recipients : [], should_send, detail, subject: `[EcoScan] Rappel de paiement — facture ${facture.numero ?? ''}`, text } }];
